<script setup>
import{computed,onMounted,ref}from'vue'
import{AlertTriangle,BookOpenCheck,Download,RefreshCw,ShieldCheck,Sparkles,Target}from'@lucide/vue'
import{acquireMarketplaceListing,createMarketplaceRecommendation,getLatestMarketplaceRecommendation}from'../api/marketplace'

const run=ref(null),busy=ref(''),error=ref(''),notice=ref('')
const goals=ref('可信训练,人工智能'),topics=ref('AI'),difficulty=ref(0.5)
const items=computed(()=>run.value?.items||[])
const suitability={recommended:'优先推荐',consider:'可以考虑',limited:'有限适配',not_applicable:'暂不适用'}
const pct=value=>`${Math.round(Number(value||0)*100)}%`
function msg(e){return e?.detail?.message||e?.detail||e?.message||'操作失败'}
function list(value){return value.split(',').map(x=>x.trim()).filter(Boolean)}
async function load(){busy.value='load';error.value='';try{run.value=await getLatestMarketplaceRecommendation()}catch(e){error.value=msg(e)}finally{busy.value=''}}
async function generate(){busy.value='generate';error.value='';notice.value='';try{run.value=await createMarketplaceRecommendation({learning_goals:list(goals.value),topics:list(topics.value),target_difficulty:Number(difficulty.value)});notice.value=`已冻结推荐运行 ${run.value.id}` }catch(e){error.value=msg(e)}finally{busy.value=''}}
async function acquire(item){busy.value=`acquire:${item.listing.id}`;error.value='';try{const result=await acquireMarketplaceListing(item.listing.id);notice.value=`已获取课程副本 ${result.derived_course_id}` }catch(e){error.value=msg(e)}finally{busy.value=''}}
onMounted(load)
</script>

<template><main class="recommend-page" data-testid="marketplace-recommendations"><header><div><p>EXPLAINABLE MARKETPLACE RANKING</p><h2>市场可解释智能推荐</h2><span>把学习目标、画像与可核验证据拆开评分，而不是按热度简单排序</span></div><button class="icon" aria-label="刷新推荐运行" @click="load"><RefreshCw :size="16"/></button></header>
<section class="truth"><ShieldCheck :size="18"/><div><strong>{{run?.truth_label||'系统可解释适配建议 · 非专家认证'}}</strong><span>{{run?.boundary||'推荐为本地确定性计算，数据不足会明确标注。'}}</span></div></section>
<p v-if="error" class="error"><AlertTriangle :size="15"/>{{error}}</p><p v-if="notice" class="notice">{{notice}}</p><p v-if="busy" class="loading"><RefreshCw :size="14"/>{{busy==='load'?'正在恢复最近推荐运行':'正在计算并冻结推荐证据'}}</p>
<section class="target-panel"><div><Target :size="18"/><h3>本次学习目标</h3></div><label>目标<input v-model="goals" aria-label="推荐学习目标" placeholder="逗号分隔"/></label><label>主题<input v-model="topics" aria-label="推荐主题" placeholder="逗号分隔"/></label><label>目标难度 <b>{{pct(difficulty)}}</b><input v-model="difficulty" aria-label="推荐目标难度" type="range" min="0" max="1" step="0.05"/></label><button :disabled="Boolean(busy)" @click="generate"><Sparkles :size="15"/>生成并冻结推荐</button></section>
<section v-if="run?.id" class="run-meta"><div><strong>运行 {{run.id}}</strong><span>算法 {{run.algorithm_version}} · 画像 {{run.profile_snapshot_id||'兼容画像/中性先验'}}</span></div><code>{{run.input_hash}}</code><small>{{run.created_at}} · {{run.result_count}} 个结果</small></section>
<section class="result-grid"><article v-for="item in items" :key="item.id" class="result" :data-suitability="item.suitability"><div class="rank"><span>#{{item.rank}}</span><em>{{suitability[item.suitability]}}</em></div><div class="title"><div><h3>{{item.listing.title}}</h3><span>{{item.listing.category}} · 课程 v{{item.listing.course_version}}</span></div><div class="score"><strong>{{pct(item.total_score)}}</strong><small>置信度 {{pct(item.confidence)}}</small></div></div><p>{{item.listing.summary}}</p><div class="tags"><span v-for="tag in item.listing.tags" :key="tag">{{tag}}</span></div><div class="reasons"><strong>推荐理由</strong><span v-for="reason in item.recommendation_reasons" :key="reason"><BookOpenCheck :size="12"/>{{reason}}</span></div><div v-if="item.unsuitable_reasons.length" class="limits"><strong>不适用或限制</strong><span v-for="reason in item.unsuitable_reasons" :key="reason"><AlertTriangle :size="12"/>{{reason}}</span></div><details><summary>查看 7 项分数贡献与证据</summary><div class="features"><article v-for="(feature,key) in item.features" :key="key"><div><strong>{{feature.label}}</strong><em>{{pct(feature.contribution)}} / 权重 {{pct(feature.weight)}}</em></div><div class="bar"><i :style="{width:pct(feature.score)}"></i></div><span>{{feature.evidence_available?'直接证据可用':'直接证据不足'}} · 原始分 {{pct(feature.score)}}</span></article></div></details><div v-if="item.evidence_state.missing_evidence.length" class="missing"><strong>数据不足说明</strong><span v-for="x in item.evidence_state.missing_evidence" :key="x">{{x}}</span></div><div class="license"><strong>{{item.listing.license.course_license||'未提供课程许可证'}}</strong><span>{{item.listing.license.course_origin||'未提供课程来源'}}</span></div><footer><code>{{item.listing.snapshot_hash}}</code><button :disabled="Boolean(busy)" @click="acquire(item)"><Download :size="14"/>获取课程副本</button></footer></article><p v-if="run&&!items.length" class="empty">当前没有已发布市场课程，无法生成推荐。</p><p v-if="!run?.id" class="empty">尚未生成推荐。填写目标后创建第一份可恢复的推荐运行。</p></section></main></template>

<style scoped>
.recommend-page{max-width:1180px;margin:0 auto;color:#26342c}header,.truth,.target-panel>div,.rank,.title,.reasons span,.limits span,footer{display:flex;align-items:center}.recommend-page>header{justify-content:space-between}.recommend-page>header p{margin:0;color:#718078;font-size:10px;font-weight:800;letter-spacing:.12em}.recommend-page>header h2{margin:4px 0;font-size:24px}.recommend-page>header span,.truth span{display:block;color:#718078;font-size:10px}.icon{display:grid;width:36px;height:36px;place-items:center;border:1px solid #dce5de;border-radius:7px;background:#fff}.truth{gap:8px;margin:14px 0;padding:11px;border-left:3px solid #3a715b;background:#eef6f1}.truth strong{display:block;font-size:11px}.target-panel{display:grid;grid-template-columns:1.2fr 1.3fr 1fr 1fr auto;gap:9px;align-items:end;padding:12px;border:1px solid #dce5de;background:#fff}.target-panel>div{gap:7px}.target-panel h3{margin:0;font-size:12px}.target-panel label{font-size:9px;font-weight:700}.target-panel input{display:block;width:100%;min-width:0;margin-top:5px;padding:9px;border:1px solid #d6e0d9;border-radius:6px}.target-panel input[type=range]{padding:0}.target-panel button,footer button{display:flex;align-items:center;justify-content:center;gap:5px;padding:9px;border:0;border-radius:6px;background:#304b3d;color:#fff}.run-meta{display:grid;grid-template-columns:1fr minmax(240px,.8fr) auto;gap:10px;align-items:center;margin:10px 0;padding:10px;background:#f1f5f2}.run-meta strong,.run-meta span,.run-meta small{display:block;font-size:9px}.run-meta code,footer code{overflow-wrap:anywhere;font-size:8px}.result-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.result{min-width:0;padding:14px;border:1px solid #dce5de;border-top:4px solid #8a9b90;background:#fff}.result[data-suitability=recommended]{border-top-color:#3a715b}.result[data-suitability=not_applicable]{border-top-color:#a55f52}.rank{justify-content:space-between}.rank span{font-size:18px;font-weight:800}.rank em{padding:4px 7px;background:#edf4ef;font-size:9px;font-style:normal}.title{justify-content:space-between;gap:10px;margin-top:8px}.title h3{margin:0;font-size:14px}.title span,.score small{display:block;color:#718078;font-size:9px}.score{flex:0 0 76px;text-align:right}.score strong{display:block;font-size:22px}.result>p{min-height:34px;font-size:10px;line-height:1.6}.tags{display:flex;flex-wrap:wrap;gap:4px}.tags span{padding:3px 6px;background:#edf3ef;font-size:8px}.reasons,.limits{align-items:flex-start;flex-direction:column;gap:4px;margin-top:9px;padding:8px;background:#eef6f1}.limits{background:#fff4ef}.reasons strong,.limits strong,.missing strong,.license strong{font-size:9px}.reasons span,.limits span{gap:4px;font-size:9px}.result details{margin-top:9px;padding:8px;border:1px solid #e1e8e3}.result summary{cursor:pointer;font-size:9px;font-weight:700}.features{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;margin-top:8px}.features article{min-width:0;padding:7px;background:#f7f9f7}.features article>div:first-child{display:flex;justify-content:space-between;gap:5px}.features strong,.features em,.features span{font-size:8px}.features em{font-style:normal}.bar{height:4px;margin:5px 0;background:#dce4de}.bar i{display:block;height:100%;background:#4c7761}.missing,.license{margin-top:8px;padding:8px;background:#fff8ec}.missing span,.license span{display:block;overflow-wrap:anywhere;font-size:8px}.license{border-left:3px solid #c8a45c;background:#fff}.result footer{justify-content:space-between;gap:8px;margin-top:10px}.result footer code{max-width:65%}.error,.notice{padding:8px;font-size:10px}.error{display:flex;gap:5px;background:#fff0ed;color:#984d42}.notice{background:#edf5ef;color:#365845}.empty{grid-column:1/-1;padding:30px;text-align:center;color:#718078;background:#fff}
.loading{display:flex;align-items:center;gap:5px;padding:8px;background:#eef4f7;color:#365568;font-size:10px}.loading svg{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}
@media(max-width:900px){.target-panel{grid-template-columns:repeat(2,minmax(0,1fr))}.run-meta{grid-template-columns:1fr}.result-grid{grid-template-columns:1fr}}
@media(max-width:600px){.target-panel{grid-template-columns:1fr}.recommend-page>header{align-items:flex-start}.title{align-items:flex-start}.features{grid-template-columns:1fr}.result footer{align-items:stretch;flex-direction:column}.result footer code{max-width:none}.run-meta code{overflow-wrap:anywhere}}
</style>
